import { createHash, randomUUID } from "node:crypto";
import type { ToolInput, ToolOutput } from "./schema.js";
export interface StoredRun { id: string; toolId: string; userId: string; createdAt: string; inputHash: string; input?: ToolInput; output?: ToolOutput; }
export interface RunQuery { toolId: string; userId: string; limit?: number; before?: string; }
export interface StorageAdapter { save(run: StoredRun): Promise<void>; list(query: RunQuery): Promise<StoredRun[]>; remove(id: string, toolId: string, userId: string): Promise<boolean>; }
export function hashInput(input: ToolInput): string { return createHash("sha256").update(JSON.stringify(input)).digest("hex"); }
export function createStoredRun(toolId: string, input: ToolInput, output: ToolOutput, userId: string, persistPayloads = false): StoredRun { return { id: randomUUID(), toolId, userId, createdAt: new Date().toISOString(), inputHash: hashInput(input), ...(persistPayloads ? { input, output } : {}) }; }
export class InMemoryStorage implements StorageAdapter { readonly runs: StoredRun[] = []; async save(run: StoredRun) { this.runs.push(structuredClone(run)); } async list(query: RunQuery) { const limit = Math.min(Math.max(query.limit ?? 25, 1), 100); return this.runs.filter((run) => run.toolId === query.toolId && run.userId === query.userId && (!query.before || run.createdAt < query.before)).sort((a, b) => b.createdAt.localeCompare(a.createdAt)).slice(0, limit).map((run) => structuredClone(run)); } async remove(id: string, toolId: string, userId: string) { const index = this.runs.findIndex((run) => run.id === id && run.toolId === toolId && run.userId === userId); if (index < 0) return false; this.runs.splice(index, 1); return true; } }
