import { z } from "zod";
export const roleplayMessageSchema = z.object({ role: z.enum(["learner", "prospect"]), content: z.string().trim().min(1).max(4_000) }).strict();
export const inputSchema = z.object({ stage: z.string().trim().min(1).max(120), userInput: z.string().trim().min(1).max(4_000), conversationHistory: z.array(roleplayMessageSchema).max(40), scenario: z.object({ scenarioSetup: z.string().min(1), prospectProfile: z.object({ name: z.string(), role: z.string(), personality: z.string(), priorities: z.array(z.string()), concerns: z.array(z.string()) }).strict(), successMetrics: z.array(z.string()) }).strict().optional(), speechAnalysis: z.object({ pace: z.number().min(0).max(100).optional(), clarity: z.number().min(0).max(100).optional(), fillerWordCount: z.number().int().min(0).optional() }).strict().optional() }).strict();
export const outputSchema = z.object({ prospectResponse: z.string().min(1), coachingTip: z.string().min(1), emotionalTone: z.enum(["open", "neutral", "skeptical", "concerned", "frustrated", "reassured"]), difficultyAdjustment: z.enum(["easier", "same", "harder"]), evaluation: z.object({ score: z.number().min(0).max(100), empathy: z.number().min(0).max(100), discovery: z.number().min(0).max(100), clarity: z.number().min(0).max(100), evidence: z.array(z.string().min(1)).max(5), nextMove: z.string().min(1) }).strict(), sessionComplete: z.boolean() }).strict();
export type ToolInput = z.infer<typeof inputSchema>; export type ToolOutput = z.infer<typeof outputSchema>;
